import '@pancakeswap/v3-core/contracts/interfaces/IDackieV3Factory.sol';
import '@pancakeswap/v3-core/contracts/interfaces/IDackieV3Pool.sol';

import './PeripheryImmutableState.sol';
import '../interfaces/IPoolInitializer.sol';

/// @title Creates and initializes V3 Pools
abstract contract PoolInitializer is IPoolInitializer, PeripheryImmutableState {
    /// @inheritdoc IPoolInitializer
    function createAndInitializePoolIfNecessary(
        address token0,
        address token1,
        uint24 fee,
        uint160 sqrtPriceX96
    ) external payable override returns (address pool) {
        require(token0 < token1);
        pool = IDackieV3Factory(factory).getPool(token0, token1, fee);

        if (pool == address(0)) {
            pool = IDackieV3Factory(factory).createPool(token0, token1, fee);
            IDackieV3Pool(pool).initialize(sqrtPriceX96);
        } else {
            (uint160 sqrtPriceX96Existing, , , , , , ) = IDackieV3Pool(pool).slot0();
            if (sqrtPriceX96Existing == 0) {
                IDackieV3Pool(pool).initialize(sqrtPriceX96);
            }
        }
    }
}

